mapper.select:
select count(*) from contract_visa
where type = 1

    and project_id = #{projectId}


    and mode = #{mode}

SELECT cv.id, cv.create_time, cv.update_time, cv.bool_delete_enum, cv.version, cv.type, cv.`mode`, cv.project_id, cv.serial_number, cv.visa_date, cv.user_id, cv.user_name, cv.reason_id, cv.reason_name, cv.visa_amount, cv.breach_amount, cv.settlement_date, cv.settlement_amount, cv.processing_settlement_amount, cv.business_type, cv.create_user_id, cv.create_user_name, cv.check_user_id, cv.check_user_name, cv.`status`, cv.supervision_unit, cv.design_unit, cv.government_regulation, cv.remark, cv.attachment_ids, cv.attachment_remark FROM contract_visa cv INNER JOIN contract_project cp ON cp.id = cv.project_id WHERE cp.bool_delete_enum =0 AND cv.bool_delete_enum =0
and cv.project_id=#{projectId}
and cv.status=#{status}
and cv.user_name like concat('%',#{userName},'%')
and cv.check_user_name like CONCAT('%',#{checkUerName},'%')
and cv.mode=#{mode}
and DATE_FORMAT(cv.create_time, '%Y')= #{year}
and cv.business_type=#{businessType}
and cv.type=#{type}
order by cv.id desc

select count(*) from contract_visa where type = 1
and DATE_FORMAT(#{date}, '%Y%m%d') = DATE_FORMAT(create_time, '%Y%m%d')
and mode = #{mode}
